// Original course material; primary protocol references accompany the lessons.
const R=(n,title)=>({title:`RFC ${n} · ${title}`,url:`https://www.rfc-editor.org/rfc/rfc${n}`});
const src={ip:R(791,'IPv4'),arp:R(826,'ARP'),dhcp:R(2131,'DHCP'),nat:R(3022,'NAT'),ipv6:R(8200,'IPv6'),tcp:R(9293,'TCP'),udp:R(768,'UDP'),dns:R(1034,'DNS'),tls:R(8446,'TLS 1.3 · foundational specification'),http:R(9110,'HTTP semantics'),h2:R(9113,'HTTP/2'),h3:R(9114,'HTTP/3'),quic:R(9000,'QUIC'),cookies:{title:'MDN · HTTP cookies',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies'},capture:{title:'Wireshark · User’s Guide',url:'https://www.wireshark.org/docs/wsug_html_chunked/ChapterIntroduction.html'}};
export const chapters=[{title:'The local network',subtitle:'From an application to the first hop'},{title:'Beyond your router',subtitle:'Configuration, routes and addressing'},{title:'Delivery & discovery',subtitle:'Connections, reliability and names'},{title:'Trust & the web',subtitle:'From a DNS answer to an HTTP response'},{title:'The modern Internet',subtitle:'Streams, sessions and intermediaries'},{title:'Investigate & reason',subtitle:'Read evidence and understand failures'}];
const S=(title,text)=>({title,text});
const Q=(kind,prompts,answer,checks)=>({kind,prompts,answer,checks});
const L=(id,title,summary,terms,sections,trace,example,trap,questions,sources)=>({id,title,summary,terms,sections,trace,example,trap,questions,sources});
export const lessons=[
L('layers','A request is a journey','Follow one message through nested layers, separating a destination from a next hop.',['protocol','packet','frame','encapsulation'],[
S('Start with a message','Your browser wants to send a request to a web server. A protocol is an agreement about message structure and behavior: which fields appear, what they mean, and what each side should do next. Several protocols cooperate because reaching another application involves several separate problems.'),
S('One envelope inside another','For HTTPS using HTTP/1.1 over TCP, HTTP data is protected by TLS, carried in a TCP byte stream, placed in IP packets, and sent over a local link. On Ethernet, the local envelope is a frame. Each layer adds information for its own task. This nesting is encapsulation. HTTP/3 will use a different transport arrangement.'),
S('The next hop and the destination','For a remote server, the IP destination identifies the server while the first Ethernet destination identifies the local router. Each router removes the incoming link envelope and creates a new one for the next link. The destination IP ordinarily stays the same, with exceptions such as address translation.'),
S('Turn layers into questions','Ask: what application message is sent, which transport carries it, which IP destination is used, and who receives it on this link? Working Wi-Fi establishes something about a local connection. DNS, routing and remote services can still fail. A browser error needs investigation rather than a guess.')
],'HTTP → TLS → TCP → IP → local frame\nLaptop → router → ISP → … → server',
['Browser prepares application data.','IP identifies the remote destination.','A local frame carries the packet to a next hop.','Each router rebuilds the local envelope.'],
'Opening a website does not always begin with a new DNS query. Caches, connection reuse and background traffic change the sequence.',[
Q('Explain',['Why can one outgoing message contain both a router’s address and a server’s address?','Explain the final destination versus the next hop.'],'They answer different questions. The IP destination identifies the remote endpoint. On the first Ethernet link, the destination MAC identifies the next-hop router. The router removes that frame and builds another link envelope for the next link.',['IP identifies remote endpoint','Frame identifies local next hop','Link envelope changes at routers']),
Q('Predict',['Could a laptop be connected to Wi-Fi while websites fail? Explain.','What does the Wi-Fi connection icon establish, and what can still be broken?'],'It establishes a local wireless connection. Usable IP configuration, routing, name resolution, transport connectivity, TLS and the remote application remain separate dependencies. Diagnose those rather than treating the Wi-Fi icon as an end-to-end test.',['Local connection only','DNS or routing can fail','Remote services can fail']),
Q('Reason',['Why might opening a website produce no new DNS query or TCP handshake?','Which existing state can let a browser skip network setup?'],'A usable DNS answer may be cached, and an established reusable connection can carry another request. Browser content caches can sometimes satisfy a request without contacting the server at all. The observed sequence depends on existing state.',['DNS cache','Connection reuse','Possibly cached content'])
],[src.ip,src.http]),
L('ethernet','Frames, switches & Wi-Fi','Understand local delivery before asking a router to carry a packet further.',['MAC address','switch','broadcast','access point'],[
S('Local delivery has its own addresses','Ethernet frames contain source and destination MAC addresses, a payload type and error-detection information. A MAC is a link-layer identifier used for local delivery. It is not a verified device identity: software can change or impersonate addresses.'),
S('How a switch learns','A typical switch learns which source MAC addresses appear on which ports. A known unicast destination goes toward its learned port. An unknown unicast may be flooded within the VLAN. Broadcasts also reach the relevant broadcast domain. A VLAN is a logical separation of a local network.'),
S('Where wireless fits','Wi-Fi has its own frames and radio-access rules. An access point commonly bridges wireless clients to a wired network. The home box called a router often combines an access point, a switch, routing, DHCP and NAT. These are separate functions even when they share one enclosure.'),
S('Know the boundary','Switching moves frames within a local network; routing forwards IP packets between networks. An ordinary router does not forward Ethernet broadcasts into the next network. This boundary explains why ARP discovers local neighbors rather than arbitrary Internet servers.')
],'Switch learns: source MAC → incoming port\nKnown unicast → learned port\nBroadcast → other eligible ports in the VLAN',
['A sends; switch learns A’s source port.','Unknown B may cause flooding within the VLAN.','B replies; switch learns B’s source port.','Later known unicast can be forwarded selectively.'],
'Learning a MAC address establishes a forwarding location, not authentication.',[
Q('Predict',['How can a switch deliver the first frame before learning the destination?','What happens to an unknown unicast on a typical Ethernet switch?'],'It learns the source from the incoming frame and may flood the unknown unicast to other eligible ports in the same VLAN. A reply lets it learn the destination’s location.',['Learns source addresses','Unknown unicast may be flooded','Scope is the VLAN']),
Q('Explain',['Which separate jobs can a home “router” combine?','Why is “the router” ambiguous for a home networking box?'],'It often combines a Wi-Fi access point, Ethernet switch, IP router, DHCP service and IPv4 NAT. Local connectivity, forwarding between networks, configuration and translation are distinct jobs.',['Access point and switch','Routing between networks','DHCP and NAT are distinct']),
Q('Security',['Why is a MAC-address allowlist a weak identity check?','What does a copied MAC address tell you about trusting addresses?'],'MAC addresses can be copied or changed in software. A matching address does not prove that the device or user is authorized. Strong identity needs authentication rather than only a local delivery identifier.',['Address can be impersonated','Identifier is not identity proof','Authentication is separate'])
],[src.arp]),
L('subnets','IPv4 addresses & subnets','Calculate whether a destination is on-link instead of guessing from its appearance.',['IPv4','prefix','subnet','default gateway'],[
S('An address plus a boundary','IPv4 addresses have 32 bits. A prefix length counts the leading network bits. In 192.168.1.10/24, the first 24 bits identify the subnet. The corresponding mask is 255.255.255.0. The mask is local configuration, not part of every destination address field.'),
S('Make the on-link decision','With an ordinary connected /24 route, 192.168.1.10 treats 192.168.1.80 as on-link: a bitwise AND with the mask produces the same network prefix. A destination outside the prefix typically needs a gateway. More specific routes can change the decision, so the routing table remains authoritative.'),
S('Work a smaller subnet','For 192.168.1.70/26, the mask is 255.255.255.192. Blocks contain 64 addresses. This address belongs to 192.168.1.64/26, covering .64–.127. In a conventional LAN, .64 is the network address, .127 the broadcast and .65–.126 ordinary host addresses.'),
S('A wrong mask changes behavior','Two hosts can share a physical switch and disagree about what is on-link. A host might try ARP for a destination that needs a gateway, or send a local destination toward a router. A correct address alone is insufficient: prefix, routes and return path also matter.')
],'192.168.1.10/24\n192.168.1.80 → connected prefix\n198.51.100.20 → default gateway, if configured',
['Write address and prefix together.','Compare destination bits under the mask.','For /26, find the containing block of 64.','Consult routes to select the next hop.'],
'“Same first three numbers” only works for /24. /31 point-to-point and /32 host routes have special uses.',[
Q('Calculate',['For 192.168.1.70/26, calculate network, broadcast and whether .120 is in the subnet.','Show the address range containing 192.168.1.70/26. Is .120 local under this prefix?'],'A /26 has blocks of 64 addresses. This block runs .64–.127. The network is 192.168.1.64, the conventional broadcast is .127, and .120 is within the subnet and an ordinary host address.',['Block size 64','Network .64, broadcast .127','.120 is within prefix']),
Q('Predict',['192.168.1.10/24 sends to 198.51.100.20 using default gateway .1. Which IP needs local MAC resolution?','For that remote destination, identify the next hop and the IP packet’s destination.'],'The selected next hop is 192.168.1.1. Resolve that gateway’s MAC for local frame delivery. The IP packet remains addressed to 198.51.100.20.',['Remote address outside /24','Resolve gateway MAC','Keep remote destination IP']),
Q('Diagnose',['Why might two hosts sharing a switch fail to communicate with mismatched subnet masks?','Why does a shared physical network not guarantee correct IP delivery?'],'The mask affects the connected route and local-versus-gateway decision. Hosts can choose inconsistent delivery methods or return paths. Link connectivity cannot correct inconsistent IP configuration.',['Mask influences routing','Wrong ARP or gateway choice','Return path matters'])
],[src.ip]),
L('arp','ARP: finding the next hop','Connect an IPv4 routing decision to the Ethernet frame that leaves the laptop.',['ARP','neighbor cache','next hop','broadcast'],[
S('IP chose a next hop. Now what?','To send on Ethernet, a host needs a destination MAC. ARP maps an on-link IPv4 address to a link address. The host first checks its neighbor cache. A usable cached entry avoids a new exchange.'),
S('Ask the local network','Without a mapping for gateway 192.168.1.1, the laptop broadcasts a request asking who owns that address. The owner normally replies directly with its MAC. Ordinary routers do not carry this broadcast across the Internet.'),
S('Keep destinations separate','For remote 198.51.100.20, the laptop resolves the gateway’s MAC. The frame can have destination AA:AA:AA:AA:AA:01 while its enclosed IP packet has destination 198.51.100.20. The router then performs its own next-link delivery.'),
S('Notice the trust assumption','Basic ARP has no cryptographic ownership proof. A malicious local participant can claim an unwanted IP-to-MAC mapping. IPv6 uses Neighbor Discovery rather than ARP. Preserve the local-neighbor concept while keeping the mechanisms separate.')
],'Broadcast: Who has 192.168.1.1?\nReply: 192.168.1.1 is at AA:AA:AA:AA:AA:01\nFrame dst = AA:…:01 | IP dst = 198.51.100.20',
['Routing selects gateway 192.168.1.1.','No usable mapping exists in the cache.','ARP resolves the gateway’s MAC.','The frame carries a remote IP packet to that router.'],
'ARP does not resolve a domain name. DNS does not supply the next-hop Ethernet address.',[
Q('Trace',['Explain the first remote IPv4 send on Ethernet with an empty ARP cache.','What happens between selecting a gateway and sending the first frame?'],'The laptop broadcasts an ARP request for the selected local gateway, receives its MAC and caches the mapping. It sends a frame to that MAC containing an IP packet addressed to the remote server.',['ARP for gateway','Broadcast request and reply','Remote IP remains destination']),
Q('Predict',['Why can a capture show web traffic without a new ARP request?','Is fresh ARP required for every outgoing packet?'],'A usable mapping may already be cached, or the exchange may predate the capture. ARP obtains or refreshes mappings when needed; it is not repeated before every packet.',['Cache reuse','Not per-packet','Capture timing']),
Q('Distinguish',['DNS returned a server IP. Why might ARP still be necessary?','What separate jobs do DNS and ARP perform here?'],'DNS supplies name-related information such as a server address. ARP supplies a local IPv4 neighbor’s link address for frame delivery. For a remote server, that neighbor is usually the gateway.',['Name-related data versus local mapping','Frame needs local destination','Usually gateway MAC'])
],[src.arp]),
L('dhcp','DHCP: joining a network','See where an address, gateway and resolver configuration can come from.',['DHCP','lease','resolver','default gateway'],[
S('Configuration before communication','DHCP can supply an IPv4 address and lease duration plus options such as subnet mask, routers and DNS resolvers. These are distinct values: a working address does not imply that the advertised resolver or gateway works.'),
S('The initial exchange','A common first lease uses Discover, Offer, Request, Acknowledge. An unconfigured client can use source 0.0.0.0 and broadcast delivery. DHCP uses UDP server port 67 and client port 68. A relay can reach a server on another network; ordinary routers do not simply forward the local broadcast.'),
S('Borrowed, not permanent','A lease grants use for a period. Clients try to renew before expiry, often first contacting the existing server directly. Renewal need not repeat the entire initial broadcast sequence. Static configuration is another possibility. Some automatically selected fallback addresses are not evidence of a successful DHCP lease.'),
S('Configuration is a trust boundary','A rogue server could advertise an unwanted gateway or resolver. Managed networks can restrict which ports may send DHCP server responses. When diagnosing a new network problem, inspect the actual lease options rather than only the assigned address.')
],'Client :68 → :67 Discover\nServer → client Offer\nClient → server Request\nServer → client Acknowledge + lease/options',
['Client asks for configuration.','Server offers a lease and options.','Client requests the selected offer.','Acknowledgement establishes the lease.'],
'DHCP supplies configuration; DNS resolves names. Their servers need not be the same machine.',[
Q('Explain',['How can a laptop with no usable IP ask DHCP for one?','Why does DHCP avoid an address-before-configuration chicken-and-egg problem?'],'Initial DHCP can use source 0.0.0.0 and local broadcast delivery. A server or relay receives the request. A common first exchange is Discover, Offer, Request, Acknowledge.',['Special initial addressing','Broadcast and server/relay','DORA sequence']),
Q('Diagnose',['DHCP succeeded but names fail. Which configuration would you inspect?','Could a valid lease coexist with a broken DNS resolver? Explain.'],'Inspect the resolver options and whether those resolvers are reachable and answering. Address, prefix, gateway and DNS configuration have independent jobs. A lease does not validate every advertised service.',['DNS resolver option','Reachability and response','Independent configuration values']),
Q('Security',['What influence could a rogue DHCP gateway option give an attacker?','Why is trusting any DHCP offer a security concern?'],'An unwanted gateway can redirect traffic through another path or disrupt it; a resolver option can affect name resolution. Correctly validated TLS still limits HTTPS impersonation because redirection alone does not grant the intended server’s private key.',['Path redirection','Resolver influence','TLS remains independent defense'])
],[src.dhcp]),
L('routing','Routing, ICMP & packet size','Follow forwarding decisions and understand the limits of a reachability test.',['route','longest prefix match','TTL','MTU','ICMP'],[
S('Each router makes a local decision','Routing entries associate destination prefixes with next hops or other actions. Among matching forwarding prefixes, longest prefix match chooses the most specific. Other policy and metrics select eligible routes. A packet need not contain a complete itinerary through the Internet.'),
S('Limit loops','An IPv4 router decrements TTL when forwarding. It behaves as a hop limit despite its historical name. On expiry, the packet is discarded and ICMP Time Exceeded may be sent. Traceroute uses small limits to discover responding hops. Missing responses may reflect filtering or rate limiting.'),
S('Fit the next link','MTU is the maximum IP packet size supported by a link. A smaller link on the path can require a sender to reduce size. IPv4 fragmentation depends on flags and behavior; IPv6 routers do not fragment forwarded packets. Path MTU discovery uses feedback or probing to find a workable size.'),
S('Interpret probes narrowly','Ping commonly tests ICMP echo. A reply shows that this exchange worked, not that TCP 443 or the web application works. Failure does not prove HTTPS cannot work, because filtering differs. Return traffic also needs a route, which need not match the forward path.')
],'198.51.100.0/24 → router A\n198.51.100.128/25 → router B\n0.0.0.0/0 → router C',
['For .150, both /24 and /25 match.','The more specific /25 selects B.','Router decrements TTL and creates the next-link envelope.','Replies need a working return path.'],
'One successful probe is evidence for that exchange, not a guarantee for every application.',[
Q('Calculate',['Where does 198.51.100.150 go using the displayed table?','Why does the /25 win over the matching /24 and default route for .150?'],'It matches both the /24 and .128/25. Longest prefix match chooses /25 and router B. The default /0 is less specific than either.',['Both prefixes match','/25 most specific','Router B']),
Q('Diagnose',['Ping fails but HTTPS succeeds. Is that contradictory?','Why does failed ping not prove a web server is down?'],'No. ICMP echo and HTTPS test different protocols and policies. Echo may be filtered or rate-limited while web traffic is allowed. Interpret the exact observation instead of declaring all connectivity broken.',['Different protocols','Filtering/rate limits','Narrow interpretation']),
Q('Reason',['Small messages work but large transfers stall. What path property could you investigate?','How could an MTU problem depend on packet size?'],'A restrictive path MTU may drop larger packets while small ones fit. Investigate packet-too-big or fragmentation-needed feedback and sender size adjustment. This is a hypothesis: loss and application behavior can cause similar symptoms.',['Size versus path MTU','Feedback and adjustment','Other causes remain possible'])
],[src.ip,src.ipv6]),
L('nat','NAT: sharing an IPv4 address','Track translation state from an outgoing flow to its returning reply.',['NAT','port','flow','private address'],[
S('Several clients share one address','Private IPv4 addresses are not ordinary globally routed destinations. Address-and-port translation rewrites an outgoing source address and often source port. Multiple internal flows can share one external address while remaining distinguishable.'),
S('Follow a mapping','192.168.1.10:53000 to 198.51.100.20:443 may leave as 203.0.113.5:62001 to that server. The router records state to match replies and translate them back. The external-looking addresses here are documentation ranges, not actual live Internet endpoints.'),
S('Inbound traffic needs planning','An unsolicited packet may have no mapping identifying an internal recipient. Port forwarding creates a configured mapping. Other traversal arrangements are possible. Carrier-grade NAT adds an upstream translation layer, so controlling your home router may not establish public inbound reachability.'),
S('Translation differs from filtering','NAT changes addressing; a firewall enforces policy. Home boxes commonly do both and reject unsolicited inbound traffic, but translation is not a substitute for explicit filtering. IPv6 can use globally addressed hosts with restrictive stateful firewalls and no IPv4-style address sharing.')
],'Inside:  192.168.1.10:53000 → 198.51.100.20:443\nOutside: 203.0.113.5:62001 → 198.51.100.20:443\nReply → reverse translation using flow state',
['Client creates an outgoing flow.','Router allocates a mapping.','Server replies to the translated endpoint.','Router translates and forwards internally.'],
'A public IP does not identify a unique device or person. Many clients may share it.',[
Q('Trace',['How does a reply to 203.0.113.5:62001 reach 192.168.1.10:53000?','Why does this translation example need recorded state?'],'The router matches the reply to a recorded flow mapping, reverses the address/port translation and forwards to the internal host. The public address alone does not distinguish all internal flows.',['Recorded mapping','Reverse translation','Shared public address']),
Q('Reason',['Why can home port forwarding fail behind carrier-grade NAT?','How does a second NAT layer affect unsolicited inbound traffic?'],'An upstream ISP NAT can receive the public packet without a mapping toward your router. Your rule controls only your device; it cannot configure the ISP’s mapping. Each relevant layer needs reachability or appropriate forwarding.',['Upstream translation','No upstream mapping','Local control is limited']),
Q('Distinguish',['Why does an IPv6 host still benefit from a firewall without NAT?','Explain address translation versus traffic policy.'],'Translation rewrites addressing. A firewall allows or denies traffic. Global addresses can coexist with strict stateful filtering. Security policy should be explicit rather than inferred from the presence of NAT.',['Rewriting versus permission','Global addressing with filtering','Intentional security policy'])
],[src.nat]),
L('ipv6','IPv6 & neighbor discovery','Carry the same delivery reasoning into different addressing and discovery mechanisms.',['IPv6','Neighbor Discovery','SLAAC','link-local'],[
S('Larger addresses, familiar routing questions','IPv6 uses 128-bit addresses, typically written in hexadecimal groups separated by colons. A double colon can compress one run of zero groups. Prefixes still identify address ranges. The question of local delivery versus routing remains.'),
S('Neighbors without ARP','Neighbor Discovery uses ICMPv6 messages such as Neighbor Solicitation and Advertisement. It uses multicast rather than IPv4-style broadcast. Link-local IPv6 addresses operate only on their link and are central to nearby router and neighbor communication.'),
S('Learn routers and form addresses','Router Advertisements convey default-router availability and prefix information. SLAAC lets a host form addresses using advertised information and local behavior. DHCPv6 can supply addresses or options, but default routers normally come from Router Advertisements rather than a DHCPv6 gateway option.'),
S('Two versions can coexist','A dual-stack host can use IPv4 and IPv6. DNS A and AAAA records supply candidate addresses. Client connection strategies may try different candidates. IPv6 does not automatically authenticate peers or enforce firewall policy. Blocking all ICMPv6 can break essential control functions.')
],'Router Advertisement → prefixes + default-router information\nNeighbor Solicitation ↔ Neighbor Advertisement\nDNS A → IPv4 | AAAA → IPv6',
['Receive router information locally.','Configure suitable addresses.','Use Neighbor Discovery for local delivery.','Forward remote traffic through an IPv6 router.'],
'IPv6 is not just IPv4 with longer numbers: local discovery, broadcasts and configuration differ.',[
Q('Explain',['How does IPv6 learn a local neighbor’s link address without ARP?','What replaces ARP’s local resolution role in IPv6?'],'ICMPv6 Neighbor Discovery uses Neighbor Solicitation and Advertisement to learn or verify local neighbor information. Relevant requests use multicast rather than IPv4 broadcast.',['ICMPv6 Neighbor Discovery','Solicitation/Advertisement','Multicast']),
Q('Predict',['Why can blocking all ICMPv6 break ordinary traffic?','Why is ICMPv6 more than optional ping?'],'It carries essential functions including Neighbor Discovery and packet-too-big feedback. Blanket blocking can prevent local communication or path MTU adjustment. Policy must account for required control messages.',['Neighbor Discovery','MTU feedback','Required control traffic']),
Q('Distinguish',['Where does an IPv6 host normally learn its default router?','How do Router Advertisements differ from DHCPv6?'],'Default-router information normally comes from Router Advertisements. SLAAC can use advertised prefixes. DHCPv6 can supply addresses or other options but normally does not supply the default gateway like IPv4 DHCP does.',['Router Advertisements','SLAAC prefixes','Different DHCPv6 role'])
],[src.ipv6]),
L('tcp-connect','TCP: opening a connection','Distinguish endpoint addressing, connection setup and application success.',['TCP','port','socket','handshake'],[
S('Reach an application endpoint','Transport ports help an operating system direct traffic to endpoints. A TCP connection is identified by the source and destination addresses and ports. A client usually uses a temporary source port while a server listens on a configured port.'),
S('Establish shared state','The usual opening is SYN, SYN-ACK, ACK. Each side contributes an initial sequence number and acknowledges the other. SYN consumes sequence space: acknowledging SYN sequence 1000 uses ACK 1001. This establishes synchronized connection state and evidence that communication works in both directions.'),
S('Connected is not authenticated','The TCP handshake does not authenticate a website, negotiate TLS or prove the application works. A connection to port 443 only establishes transport state with the responding endpoint. Port numbers are conventions, not proof of safe or valid content.'),
S('Refusal differs from silence','A reset can actively reject a connection. Silence can mean filtering, loss, routing failure or an unresponsive endpoint. FIN normally participates in orderly closing; RST aborts a connection. The observed traffic and vantage point constrain your interpretation.')
],'Client → SYN seq=1000\nServer ← SYN,ACK seq=7000 ack=1001\nClient → ACK ack=7001',
['Send SYN to a listening endpoint.','Peer replies with its SYN and acknowledgement.','Client acknowledges the peer’s SYN.','An application protocol can proceed.'],
'The TCP handshake is separate from TLS authentication and HTTP processing.',[
Q('Trace',['Explain what the three TCP handshake messages establish.','Why does a conventional TCP opening use SYN, SYN-ACK, ACK?'],'The client supplies an initial sequence number. The server acknowledges it and supplies its own SYN. The client acknowledges the server’s SYN. Each side establishes sequence state and evidence of communication in both directions.',['Both sequence numbers','Acknowledges both SYNs','Shared connection state']),
Q('Diagnose',['TCP connects to 443 but a certificate error follows. What succeeded?','Does a successful TCP connection prove HTTPS identity checks passed?'],'TCP connectivity to the responding endpoint succeeded. TLS validation is a separate stage that may fail for hostname, trust-chain, time or other reasons. Neither TCP success nor a port number proves authenticated HTTPS.',['TCP succeeded','TLS is separate','Application success not established']),
Q('Calculate',['What ACK acknowledges a SYN with seq=1000? Explain why.','Why is the expected ACK 1001 despite no application byte in that SYN?'],'ACK 1001 acknowledges the SYN because SYN consumes one position in sequence space. The acknowledgement names the next expected sequence number, not one byte of HTTP data.',['ACK 1001','SYN consumes sequence space','Next expected position'])
],[src.tcp]),
L('tcp-stream','TCP: bytes, loss & congestion','Reason about a reliable byte stream, receiver capacity and path limits.',['sequence number','acknowledgement','flow control','congestion control'],[
S('A byte stream, not messages','TCP preserves byte order rather than application write boundaries. One send may arrive across several reads, and multiple sends may be read together. Applications need framing such as lengths, delimiters or an application protocol’s defined structure.'),
S('Recover missing bytes','Sequence numbers locate bytes. A cumulative ACK identifies the next contiguous byte expected. Receiving bytes 1000–1099 produces ACK 1100. If 1100–1199 are missing, later bytes do not close that gap. Selective acknowledgements can report additional received ranges.'),
S('Two different limits','Flow control protects receiver capacity through an advertised receive window. Congestion control adapts sending to conditions along the network path. A receiver with spare memory does not eliminate a network bottleneck. Both mechanisms can limit a connection.'),
S('Reliability has a boundary','Persistent failure can still lead to timeout or error. A TCP ACK concerns receipt by the peer’s TCP implementation, not completion of a business action or durable storage by the application. Ordered delivery can also wait behind a missing byte range even when later data has arrived.')
],'1000–1099 received → ACK 1100\n1100–1199 missing\n1200–1299 received → cumulative ACK still 1100',
['Receive a contiguous prefix.','Detect a gap despite later arrivals.','Recover missing bytes through retransmission.','Advance ordered delivery once the gap closes.'],
'One TCP packet is not one application message. A transport ACK is not a completed transaction.',[
Q('Predict',['Two send calls occur. Must the peer receive exactly two messages with two reads?','Why does a TCP application need framing?'],'No. TCP offers ordered bytes, not send-boundary preservation. Reads can combine or split data. The application reconstructs messages using its framing rules.',['Ordered byte stream','Reads can combine or split','Application framing']),
Q('Calculate',['What cumulative ACK follows received 1000–1099, missing 1100–1199 and received 1200–1299?','What does ACK 1100 say about a gap despite later received bytes?'],'The cumulative ACK remains 1100, the next byte expected in sequence. Selective acknowledgements can describe later ranges, but ordered delivery cannot pass the gap until recovery.',['ACK 1100','Gap controls contiguous progress','Selective ACK may describe later bytes']),
Q('Distinguish',['A receiver has buffer space but the path is congested. What still limits sending?','Explain flow control versus congestion control.'],'Flow control reflects receiver capacity. Congestion control reflects the network path and can restrict sending despite a large receive window. Both protect different resources.',['Receiver capacity','Path conditions','Distinct constraints'])
],[src.tcp]),
L('udp','UDP: datagrams & responsibilities','Understand what UDP leaves to applications and what higher protocols can add.',['UDP','datagram','retransmission','QUIC'],[
S('A smaller delivery contract','UDP carries port-addressed datagrams without TCP connection establishment or its ordered stream. Delivered datagrams retain their boundaries, but UDP itself does not provide retransmission, ordering or congestion control. Loss, duplication and reordering are possible.'),
S('Choose behavior for the task','A real-time application may prefer fresh information to waiting for old missing data. Another protocol may add timeouts and retries. This is a design choice, not proof that UDP is always faster or that every UDP application should ignore reliability.'),
S('Build richer protocols above it','QUIC uses UDP but adds reliable streams, secure connection establishment, loss recovery and congestion control. A carrier’s minimal contract does not prevent a higher layer from supplying stronger behavior. Connectionless UDP does not imply every application is stateless or unencrypted.'),
S('Respect the path','Large datagrams can exceed the path’s workable size and suffer fragmentation or drops. Applications need responsible congestion behavior. A successful send call is evidence of local acceptance, not proof that the remote application received or processed the data.')
],'Sent: A then B\nPossible arrival: B then A, duplicates, or only B\nA higher protocol decides how to detect and handle this.',
['Define each datagram’s meaning.','Expect loss and reordering.','Choose deadlines, retries or tolerance.','Interpret delivered datagrams at the receiver.'],
'“Uses UDP” does not mean “cannot be reliable or encrypted.” Check the protocol above it.',[
Q('Predict',['What outcomes must a UDP application consider after sending A then B?','What does UDP leave unspecified about order and success?'],'Either can be lost, duplicated or delivered out of order. UDP itself does not restore ordering or retransmit. The application or higher protocol chooses how to tolerate or recover from these outcomes.',['Loss/reordering','Duplication','Higher-layer policy']),
Q('Reason',['How can QUIC provide reliability over UDP?','Why does using UDP not imply there is no retransmission?'],'UDP carries datagrams. QUIC implements additional state, stream reliability, loss recovery, congestion control and security above that carrier. The guarantees belong to different layers.',['UDP is carrier','QUIC adds reliability','Layer responsibilities']),
Q('Explain',['What does a successful UDP send prove about the remote application?','Why might a UDP-based protocol need a response?'],'It normally shows local acceptance for sending. Remote delivery and processing remain unproven. A protocol reply can establish additional evidence according to its defined semantics.',['Local acceptance only','Remote receipt not proven','Application reply semantics'])
],[src.udp,src.quic]),
L('dns','DNS: delegation & caches','Trace name resolution without imagining that each browser queries the root.',['DNS','recursive resolver','authoritative server','TTL'],[
S('A distributed name database','A and AAAA records supply IPv4 and IPv6 addresses. CNAME supplies aliases. Names can have multiple records, and one IP can serve many names. DNS contains other record types as well; it is more general than a single name-to-address table.'),
S('Ask a recursive resolver','A client commonly queries a configured recursive resolver. It can answer from cache or query other servers. With no relevant cache, it follows root referrals to a top-level domain and then an authoritative server for the relevant zone. The browser normally does not perform the entire referral chain itself.'),
S('Delegation divides responsibility','Authoritative servers publish data for zones; recursive resolvers obtain answers for clients. These are different roles even if one implementation can do both. Delegation allows separate organizations to operate different namespace portions.'),
S('Cache lifetime changes the journey','A record’s TTL bounds ordinary cache reuse. Cached answers or referrals can shorten resolution. Different caches expire at different times. DNS TTL is time in seconds, whereas IP TTL limits forwarding hops. Negative answers can also be cached under their own rules. Traditional DNS uses UDP and TCP on port 53; a truncated UDP answer can lead to a TCP retry. TCP is not limited to zone transfers.')
],'Device → recursive resolver\nCache miss: root → TLD → authoritative referrals\nCache hit: use cached data within applicable lifetime',
['Check caches.','Follow delegation if necessary.','Obtain authoritative data.','Return and cache the answer under applicable rules.'],
'The resolver need not carry later web traffic. It supplies information for a separate connection.',[
Q('Trace',['Who follows root-to-authoritative referrals for a normal client lookup with empty caches?','Explain the recursive resolver’s path with no relevant cached information.'],'The client asks its recursive resolver. The resolver follows root, top-level-domain and authoritative referrals, retrieves relevant records and returns an answer. It can cache data along the way.',['Client asks resolver','Delegation/referrals','Authoritative data and caching']),
Q('Predict',['Why can an authoritative change remain invisible to some clients for a while?','How can two clients temporarily receive old and new DNS answers?'],'Previously cached data can remain usable until its lifetime expires. Caches were populated at different times. Updating an authoritative record does not erase every downstream copy immediately.',['Existing cache lifetime','Different cache timing','No instant global invalidation']),
Q('Distinguish',['What does TTL mean in DNS versus IP?','Why should a DNS TTL of 300 not be interpreted as 300 routing hops?'],'DNS TTL is an ordinary cache lifetime in seconds. IPv4 TTL is decremented by forwarding routers and acts as a hop limit. The same abbreviation names different mechanisms.',['DNS seconds','IP forwarding hops','Different roles'])
],[src.dns]),
L('dns-trust','DNS failures & trust','Separate a negative answer, a false answer and an encrypted resolver connection.',['NXDOMAIN','DNSSEC','DoH','DoT'],[
S('Read the failure precisely','NXDOMAIN is a received answer saying the queried name does not exist. SERVFAIL means resolution failed, for several possible reasons. A timeout means no usable response arrived within the waiting period. These are different observations, and none alone proves a web application is down.'),
S('Encryption protects a particular hop','DNS over HTTPS and DNS over TLS protect the client-to-resolver transport. The resolver still sees the query. Transport encryption does not establish that the resolver supplied correct data or hide every piece of network metadata.'),
S('Authenticity is separate','DNSSEC lets validating resolvers verify signed DNS data through a chain of trust. It supports data authenticity and integrity, not query confidentiality. Not every zone is signed. Validation problems and unsigned data need careful interpretation rather than a blanket trust verdict.'),
S('Change one variable at a time','Record the name, resolver, record type, response code and caches. Compare a known-good resolver when appropriate, while recognizing legitimate split DNS or geographic answers. Replacing every setting can hide the original cause instead of explaining it.')
],'NXDOMAIN → negative answer\nSERVFAIL → resolution failure\nTimeout → no usable reply in time\nDoH/DoT → protected transport to a resolver',
['Record exact lookup and response.','Distinguish an answer from silence.','Inspect cache and resolver behavior.','Check later connection stages separately.'],
'An encrypted resolver connection does not make the resolver incapable of supplying false data.',[
Q('Distinguish',['How do NXDOMAIN and a timeout differ?','Why investigate a negative answer differently from no response?'],'NXDOMAIN is a received negative answer about the name. A timeout is absence of a usable reply within the waiting period. Check name existence and negative caches for the first, and path, filtering, resolver availability or loss for the second.',['Negative versus absent response','Different hypotheses','Neither proves web app failure']),
Q('Security',['Can a DoH resolver still see queries or supply a false answer?','What does DoH protect, and what trust remains?'],'The resolver terminates the protected connection and sees the query. DoH protects client-to-resolver transport, not the correctness of the resolver’s data. Resolver trust and DNSSEC validation remain separate.',['Resolver sees queries','Transport scope','Data authenticity is separate']),
Q('Explain',['Why does DNSSEC not replace encrypted DNS?','Why can signed data and encrypted transport be useful together?'],'DNSSEC supports authenticity and integrity of signed data without concealing the query. Encrypted DNS protects a transport hop without independently proving data came from the zone owner. They address different properties.',['Authenticity/integrity','Transport confidentiality','Complementary roles'])
],[src.dns]),
L('tls-identity','TLS: who are you talking to?','Understand certificates as identity claims bound to keys and a trust chain.',['TLS','certificate','certificate authority','hostname'],[
S('Identify the encrypted peer','TLS protects communication from eavesdropping and modification while supporting peer authentication. Ordinary HTTPS browsers authenticate the server using certificates. Encryption without identity checks could create a private channel to the wrong endpoint.'),
S('Validate the binding','A certificate includes public-key information and valid names, signed by an issuer. A browser checks the expected hostname, validity period, chain to an accepted trust anchor and other rules. The handshake must also demonstrate possession of the relevant private key; presenting a certificate alone is insufficient.'),
S('Names matter after routing succeeds','A TCP connection to the correct IP can still produce a name mismatch. Several sites can share an address. Replacing the hostname with a bare IP changes the requested identity and hosting context, so it is not an equivalent HTTPS test.'),
S('Identity is a specific claim','A valid certificate does not certify honest business practices, safe content or secure application code. An attacker can hold a valid certificate for a lookalike domain they control. Check the intended name and understand what the trust model actually establishes.')
],'Expected hostname → certificate name check\nCertificate → issuer chain → trusted root\nHandshake → proof of private-key possession',
['Know the intended name.','Validate certificate and chain.','Verify handshake authentication.','Exchange protected application data.'],
'Certificates and public keys are public. The corresponding private-key capability is what must remain secret.',[
Q('Security',['Can an attacker impersonate a server by copying only its public certificate?','What is missing from a copied certificate alone?'],'Normally no. The peer must demonstrate the relevant private-key capability during the authenticated handshake. Copying public signed information supplies no such proof. Subverted trust or validation is a separate attack path.',['Certificate is public','Private-key proof needed','Trust/validation still matter']),
Q('Diagnose',['Why can a bare-IP URL fail certificate checks when the hostname URL works?','Why is replacing a name with its IP not a transparent HTTPS test?'],'The browser expects the identity in the URL. A hostname certificate may not cover the literal IP, and name-based hosting can select different behavior. Network delivery can succeed while the requested identity fails.',['URL sets expected identity','IP may not be covered','Virtual hosting differs']),
Q('Reason',['A phishing domain has a valid HTTPS certificate. Is this contradictory?','What does a valid certificate establish about a website’s honesty?'],'No. The certificate can correctly identify the attacker’s own domain. TLS validates an identity binding under a trust model; it does not certify intent or content. The exact intended domain remains important.',['Attacker owns different domain','Identity is not honesty','Exact name matters'])
],[src.tls]),
L('tls-handshake','TLS: establishing shared secrets','Follow a simplified modern handshake and locate the endpoint of protection.',['key exchange','session key','SNI','TLS termination'],[
S('Agree on a protected session','A simplified fresh TLS 1.3 handshake over TCP starts with ClientHello, supported parameters and a key share. The server selects parameters and contributes a key share. In a usual ephemeral exchange, both derive secrets without transmitting the resulting traffic keys.'),
S('Join authentication to the exchange','The server supplies authenticated handshake material, typically including certificates and private-key proof. Finished messages check handshake integrity. This model omits resumption, client certificates and other options. A real trace may legitimately show another sequence.'),
S('Separate key roles','Certificate keys support identity verification. Handshake-derived symmetric traffic keys protect bulk application data. The browser does not simply encrypt all HTTP with the certificate’s public key. Authentication and key agreement are connected but distinct operations.'),
S('Locate termination','A CDN or reverse proxy may terminate browser TLS and create a separate origin connection. The terminating endpoint can process plaintext. Protection onward depends on that separate connection. Standard unencrypted ClientHello can expose a name through SNI; encrypted client hello deployment changes that visibility.')
],'ClientHello + key share →\n← ServerHello + key share\n← protected authentication messages\nFinished ↔ Finished\nProtected application data ↔',
['Negotiate and exchange shares.','Derive shared secrets and keys.','Authenticate and verify integrity.','Use traffic keys for application data.'],
'This is a simplified fresh handshake. Resumption and early data introduce additional behavior and replay considerations.',[
Q('Explain',['Why does TLS use certificate-related keys and symmetric traffic keys?','Why is “all HTTP is encrypted with the certificate’s public key” incomplete?'],'Certificate-related operations authenticate the peer. Key agreement derives secrets, producing symmetric traffic keys for application data. These roles are tied together by the handshake but are not the same operation.',['Authentication','Key agreement','Symmetric bulk protection']),
Q('Security',['Who can read plaintext when a CDN terminates TLS?','Does browser-to-CDN TLS automatically protect the CDN-to-origin connection?'],'The terminating CDN can access plaintext as part of serving or proxying it. Its connection to the origin is a separate leg needing its own protection and validation. Browser TLS alone does not establish security for that leg.',['Terminator sees plaintext','Separate origin leg','Separate protection needed']),
Q('Reason',['Does HTTPS hide all destination information from a passive observer?','Which metadata can remain visible around encrypted web traffic?'],'Addresses, timing and sizes can remain visible. DNS or unencrypted SNI may expose names depending on configuration; encrypted DNS and encrypted client hello alter particular observations. Visibility depends on mechanism and vantage point.',['Addresses/timing/sizes','Names depend on deployment','Observer location matters'])
],[src.tls]),
L('http','HTTP: requests, responses & caching','Read the application exchange above transport and security.',['HTTP','method','status code','cache validator'],[
S('A structured conversation','An HTTP request identifies a method and target, carries fields and may contain a body. A response has status and fields, with a body when applicable. GET asks for a representation; POST requests processing according to resource semantics. These meanings persist across wire versions.'),
S('Status is evidence','A 200 reports success under the request semantics. A 404 reports no current representation or unwillingness to disclose one. A 500 reports an error at the responding service. A real HTTP error means an endpoint answered; it does not establish that every backend is healthy.'),
S('Reuse and revalidate','Caches can reuse eligible responses under caching rules. ETag is a validator sent back in If-None-Match. For an applicable conditional request, 304 allows reuse of a stored representation rather than downloading the full body again. Revalidation still involves a network exchange.'),
S('Authority selects the site','HTTP/1.1 uses Host; newer versions have corresponding authority information. Many sites share an IP, so destination address alone does not select the intended resource. Authentication, cache variation and intermediaries also influence the response.')
],'GET /notes HTTP/1.1\nHost: example.test\nIf-None-Match: "v7"\n\nHTTP/1.1 304 Not Modified\nETag: "v7"',
['Identify resource and method.','Include a stored validator if appropriate.','Server evaluates the condition.','Client reuses content after an applicable 304.'],
'A proxy can return an HTTP error before the request reaches the intended origin application.',[
Q('Trace',['What should a client do after the displayed conditional request receives 304?','Why can revalidation succeed without a new full representation body?'],'It can reuse the stored representation under the applicable rules and response metadata. The validator avoided retransferring the full representation, while the revalidation still contacted a server.',['Reuse stored content','Conditional validator','Network exchange occurred']),
Q('Diagnose',['What can you infer from a genuine HTTP 500 response?','How does an HTTP error differ from a DNS timeout?'],'Enough of the path worked to receive HTTP from an endpoint. For HTTPS, its secure exchange also worked sufficiently. A proxy could have returned the error, so this does not prove the intended origin handled the request.',['HTTP responder reached','Earlier stages worked to responder','Origin may not have been reached']),
Q('Explain',['How can different websites share an IP and return different content?','What target information does HTTP add beyond a destination IP?'],'Host or equivalent authority information identifies the intended site at the application layer. A server or proxy selects behavior using it. HTTPS also has related TLS name selection and certificate checks.',['Authority/Host','Virtual hosting','TLS naming also matters'])
],[src.http]),
L('http-versions','HTTP/2, HTTP/3 & QUIC','Understand multiplexing and the precise waiting that independent streams reduce.',['multiplexing','HTTP/2','HTTP/3','QUIC'],[
S('Many exchanges share a connection','HTTP/2 frames separate streams within one connection so multiple exchanges can progress concurrently. Its ordinary web deployment uses TLS over TCP. Framing and header compression change the wire format while HTTP request and response meanings remain.'),
S('TCP can still make streams wait','TCP exposes one ordered byte stream. A missing range prevents delivery of later bytes through that stream, even when they carry independent HTTP/2 exchanges. Application multiplexing does not change the underlying ordering rule.'),
S('QUIC changes delivery structure','HTTP/3 maps HTTP onto QUIC, carried over UDP. QUIC supplies secure connections, loss recovery, congestion control and independently ordered streams. Missing data in one stream need not block already-received data in another solely because of one shared TCP sequence gap.'),
S('Shared limits remain','Streams share capacity, congestion control and sometimes application dependencies. HTTP/3 is not immune to loss or universally faster. Clients may fall back when UDP is unavailable. Setup state, server configuration and caches also influence observations.')
],'HTTP/2 → TLS → ordered TCP stream\nHTTP/3 → QUIC streams + TLS integration → UDP\nStreams still share network capacity.',
['Multiplex requests into streams.','Identify TCP-wide delivery gaps in HTTP/2.','QUIC supplies per-stream delivery.','Account for shared congestion and dependencies.'],
'Using UDP does not remove QUIC’s reliability or congestion control.',[
Q('Reason',['Why can one lost TCP segment delay several HTTP/2 streams?','Which head-of-line blocking remains under HTTP/2 multiplexing?'],'All frames share TCP’s ordered stream. A missing byte range holds up later bytes even when they belong to different HTTP streams. Multiplexing cannot remove that lower-layer constraint.',['Shared byte stream','Gap blocks delivery','Independent HTTP streams affected']),
Q('Explain',['How does QUIC reduce that cross-stream delivery blockage?','What changes when ordering is managed per stream?'],'QUIC independently orders reliable streams over UDP. A gap in one need not block received data in another solely due to TCP-wide ordering. Capacity, congestion and protocol dependencies still couple streams.',['QUIC over UDP','Per-stream ordering','Shared limits remain']),
Q('Predict',['UDP is blocked. Does that prove no HTTPS site can load?','What might a browser do when HTTP/3 is unavailable?'],'No. If supported, the browser and server can use HTTP/2 or HTTP/1.1 over TCP. Blocking QUIC does not block every HTTPS transport. Exact fallback behavior depends on configuration.',['QUIC affected','TCP alternatives','Support determines fallback'])
],[src.h2,src.h3,src.quic]),
L('sessions','Cookies, sessions & origins','Locate authentication state above the encrypted connection.',['cookie','session','origin','SameSite'],[
S('A connection is not a login','A server can use Set-Cookie to store browser state, attached to later eligible requests. A session cookie often contains an opaque identifier mapped to server-side session data. Other designs use signed tokens. Application state, not merely a live TCP connection, recognizes the user.'),
S('Possession can grant access','A bearer token can authorize whoever can use it until expiry, revocation or another check. TLS protects its transport span. It does not prevent leakage through application flaws, logs, browser compromise or a compromised TLS endpoint.'),
S('Flags address different risks','Secure restricts cookie transmission to secure contexts under cookie rules. HttpOnly prevents access through common JavaScript cookie APIs but does not stop automatic sending. SameSite controls some cross-site sending behavior. Domain and Path affect scope but are not strong security isolation boundaries by themselves.'),
S('Browser boundaries matter','An origin is scheme, host and port. Same-origin policy constrains script interactions. The site concept used by SameSite differs from origin. CORS governs cross-origin response access and related request rules; it is not server authentication or a universal block on cross-site requests.')
],'Set-Cookie: sid=opaque; Secure; HttpOnly; SameSite=Lax\nBrowser stores eligible cookie\nLater request → Cookie: sid=opaque\nServer validates session',
['User authenticates to the application.','Server sets a token linked to session state.','Browser sends it on eligible requests.','Server checks identity and permission for relevant actions.'],
'HttpOnly does not make injected script harmless: code may still act through the victim’s browser.',[
Q('Security',['Why can a stolen session cookie matter even when HTTPS works?','What does TLS leave unresolved about a leaked bearer token?'],'The token may be replayed through another valid connection if the server accepts it. TLS protects transit, not every storage or application boundary. Token lifetime, revocation and application checks matter.',['Bearer possession','Limited TLS scope','Session lifecycle controls']),
Q('Distinguish',['Explain Secure, HttpOnly and SameSite separately.','Which flags concern transport, script access and cross-site sending?'],'Secure restricts transmission to secure contexts. HttpOnly blocks common script access to the value. SameSite influences cross-site sending. They address different risks and are not complete application defenses.',['Transport','Script access','Cross-site sending']),
Q('Reason',['Does a CORS error prove a request never reached the server?','Why can CORS not replace authorization?'],'No. Some requests can be sent while scripts are denied response access; others require preflight success first. CORS controls browser behavior, not server-side identity or permission enforcement.',['Sending versus reading','Preflight for some requests','Server authorization required'])
],[src.cookies]),
L('edge','CDNs, proxies & load balancers','Draw actual connection endpoints instead of one imaginary browser-to-origin wire.',['CDN','reverse proxy','load balancer','origin server'],[
S('An intermediary may answer first','A reverse proxy accepts client requests and forwards selected work upstream. A load balancer distributes work among backends. A CDN uses distributed infrastructure, often caching eligible responses near users. These roles can overlap in one deployment.'),
S('Often there are two connections','Browser TLS can end at an edge proxy that opens a separate origin connection. The legs may use different protocols and protection. The origin may see the proxy’s source IP rather than the browser’s, unless trusted metadata carries client context.'),
S('Caching changes origin traffic','A cache hit can be served without an origin request. A miss or revalidation may contact the origin. Freshness, eligibility and variation rules matter, especially for personalized content. Incorrect shared caching can expose one user’s response to another.'),
S('Name the responder','A proxy can return a gateway error if it cannot obtain an appropriate upstream response. This establishes communication to that proxy, not a healthy origin exchange. Health checks establish only what their configuration tests. Correlate evidence on each leg.')
],'Browser ── TLS A ──→ edge\n                       ├─ cache hit → response\n                       └─ connection B → origin pool',
['Reach the public-facing edge.','Edge selects cache or upstream.','A separate origin leg may occur.','Response returns through the relevant connections.'],
'Forwarded client-IP headers are claims. Accept them only through correctly configured trusted proxies.',[
Q('Trace',['Why can an origin have no log entry for a page the browser successfully loaded?','Which leg may be absent when a CDN serves a cache hit?'],'The edge may satisfy the request from eligible cached content. The browser-edge exchange occurs, but no origin request is needed for that request. Browser success does not imply an origin access-log entry.',['Edge cache','No origin request','Separate observation points']),
Q('Diagnose',['What does a proxy’s 502 tell you, and what remains unproven?','Why does a gateway error not prove the origin application answered?'],'The client reached an HTTP responder reporting an upstream problem. Investigate origin reachability, TLS, timeout and response behavior. A proxy can generate the response without the origin successfully handling the request.',['Proxy answered','Upstream failure reported','Origin needs independent evidence']),
Q('Security',['What is wrong with trusting any X-Forwarded-For value?','Why must forwarded client-IP information come through trusted handling?'],'An arbitrary caller can forge header text. The server needs a known trusted proxy chain and rules for sanitizing or interpreting metadata. A header is not self-authenticating proof of a source address.',['Header can be forged','Trusted proxy chain','Validate metadata'])
],[src.http]),
L('firewalls','Firewalls & VPN boundaries','Reason about traffic policy and where a protected tunnel ends.',['firewall','stateful filtering','VPN','tunnel'],[
S('Policy over traffic','Firewalls permit or deny traffic based on rules and context such as interfaces, addresses, ports, protocols and tracked state. Stateful filtering can allow replies to an outgoing flow while rejecting unsolicited new inbound attempts. Allowed encrypted traffic can still contain unwanted application behavior.'),
S('Placement changes knowledge','A host firewall and a perimeter device see different context. Allowing TCP 443 permits a path, not proof of safe content. A TLS-terminating proxy has different visibility from a device forwarding ciphertext. State where enforcement occurs and what it can inspect.'),
S('A tunnel has endpoints','A VPN carries traffic inside another protocol, commonly with authentication and encryption. A full tunnel can route most traffic through the gateway. Split tunneling selects only some destinations. DNS handling is configuration-dependent and needs separate inspection.'),
S('Trust moves rather than disappears','A typical remote-access VPN protects the client-to-gateway span. Beyond that gateway, traffic takes an onward path. HTTPS can independently protect application traffic to its TLS endpoint. A VPN does not automatically grant anonymity or secure a compromised device.')
],'Laptop → protected VPN tunnel → gateway → destination\nVPN protection: client ↔ VPN gateway\nHTTPS protection: browser ↔ TLS endpoint',
['Find routes entering the tunnel.','Identify its gateway endpoint.','Examine policy at each boundary.','Keep independent application protection.'],
'A permitted port is not a safety certificate. A tunnel protects its own span.',[
Q('Explain',['How can a firewall permit a reply but block an unsolicited inbound flow?','Why is “all inbound is blocked” incomplete for stateful filtering?'],'Tracked state associates the reply with an allowed flow. An unrelated inbound attempt has no matching state and can be denied under policy. Exact behavior depends on rules and tracking.',['Tracked flow state','Replies associated with state','New traffic has separate policy']),
Q('Security',['Why keep HTTPS when using a VPN?','What happens to VPN protection after its gateway?'],'The tunnel ends at the VPN endpoint. Its onward path is separate; HTTPS can continue protecting application data to the TLS endpoint. They protect different spans and involve different trusted parties.',['Tunnel endpoint','Separate onward path','Independent HTTPS span']),
Q('Reason',['VPN is connected but some traffic goes directly out. What could explain this?','How does split tunneling affect “all traffic uses the VPN”?'],'Split tunneling routes only selected prefixes through the VPN, leaving other traffic on normal routes. Inspect actual routes and DNS behavior instead of relying solely on a connected icon.',['Selected prefixes','Other routes direct','Check routes and DNS'])
],[src.ip,src.tls]),
L('captures','Read a packet capture','Turn a traffic listing into bounded conclusions supported by evidence.',['capture point','display filter','retransmission','timeline'],[
S('Choose a vantage point','A capture records what a particular interface and mechanism observe. A laptop and an origin server may see different addresses because of NAT or proxies. Traffic on another interface or before recording began may be absent. Start with where and when evidence was collected.'),
S('Build a timeline','Group related endpoints and events. A fresh TCP-based web request might show DNS, TCP setup, TLS and protected data. Caches or reused connections can omit steps. Interpret the trace against known state instead of forcing every capture into one fixed story.'),
S('Filters change visibility','Wireshark display filters such as dns, arp and tcp narrow displayed packets. Capture filters control what is recorded and use different syntax. Hidden packets are not absent packets. Reading encrypted HTTP generally requires suitable endpoint secrets or instrumentation.'),
S('Annotations need interpretation','A retransmission label is analysis of observed patterns. Capture loss, offloading and observation point can cause confusing artifacts. Correlate sequence numbers, timing and endpoint logs. Use your systems or an authorized learning environment when collecting real traffic.')
],'Synthetic trace · not live traffic\n0.000 DNS response: A 198.51.100.20\n0.010 SYN → :443\n0.030 SYN,ACK ←\n0.031 ACK →\n0.040 TLS ClientHello →\n0.070 TLS alert ←',
['Record interface, time and filters.','Order the conversation events.','Find the last stage with positive evidence.','Choose a test separating remaining hypotheses.'],
'Course evidence panels are authored, simplified examples. They are not live captures or a packet simulator.',[
Q('Diagnose',['What succeeded before the TLS alert in the displayed trace?','What is justified by DNS answer → TCP opening → TLS alert?'],'A DNS response was observed and TCP setup completed to the responder. The TLS alert needs its code and context investigated. This does not show successful HTTP or establish that a certificate issue was the exact cause.',['DNS response','TCP completed','TLS alert needs context']),
Q('Reason',['No DNS appears in a filtered capture. What must you check before declaring no lookup occurred?','Why can absence from a capture be inconclusive?'],'Check capture and display filters, start time, interface and cached state. An exchange may be hidden, missed or unnecessary. Encrypted DNS can appear under another decoded transport rather than ordinary DNS.',['Filters/timing','Interface/caches','Encrypted DNS visibility']),
Q('Explain',['Why can laptop and server traces show different client IPs?','How do NAT and proxies change observations from different capture points?'],'NAT can rewrite addresses. A terminating proxy can create an independent origin connection using its own source address. Label vantage points and connection boundaries before treating observations as the same flow.',['NAT rewriting','Separate proxy connection','Labeled vantage points'])
],[src.capture]),
L('spoofing','Spoofing, poisoning & trust','Identify the forged claim and the authentication that still applies.',['spoofing','ARP poisoning','DNS poisoning','authentication'],[
S('An address is a claim','Spoofing presents a false identity or source attribute. Forging a packet’s source IP does not automatically let the sender receive replies, which ordinarily route toward the claimed source. Packet injection and a complete authenticated two-way session require different capabilities.'),
S('Poison local delivery information','ARP poisoning targets local IPv4 neighbor mappings. An unwanted mapping can associate the gateway IP with an attacker MAC and redirect or disrupt local traffic. Continuing interception may require forwarding onward. Topology and defenses affect whether the attempt works.'),
S('Poison name information','DNS poisoning introduces false name-related data into resolution or caches. It can direct a client to an attacker endpoint. Correct hostname and certificate validation still constrain ordinary impersonation of the intended HTTPS service unless additional trust failures exist.'),
S('Match defense to claim','Segmentation and switch protections address local opportunities. DNSSEC can authenticate signed DNS data. TLS authenticates an endpoint under its trust model. Each covers a different claim. Name the altered state, the component trusting it and the independent checks that remain.')
],'“Gateway IP belongs to this MAC” → neighbor information\n“This name has this IP” → DNS information\n“I control this TLS identity” → certificate + key proof',
['Name the forged claim.','Identify who accepts it.','Trace the affected traffic or state.','Check independent authentication.'],
'Redirecting traffic alone does not decrypt correctly validated TLS or supply the intended server’s private key.',[
Q('Security',['False DNS points a bank hostname at an attacker. What should validated HTTPS still require?','Why is DNS redirection alone insufficient for ordinary HTTPS impersonation?'],'The browser still requires a certificate for the intended name, an accepted chain and valid key-possession proof. A different IP does not grant those capabilities. Bypassed warnings or subverted trust can change the outcome.',['Intended hostname','Trusted chain/key proof','Redirection alone insufficient']),
Q('Reason',['Why can off-path source-IP spoofing fail to complete a TCP connection?','Where do replies to a forged source normally go?'],'Replies route toward the claimed source, not necessarily the sender. Completing TCP requires response and sequence-state handling; higher authentication adds further requirements. Injection and full impersonation are distinct.',['Replies follow claimed source','Response/state needed','Authentication adds constraints']),
Q('Distinguish',['What different information do ARP and DNS poisoning corrupt?','How do their scopes differ within the request journey?'],'ARP poisoning affects local IP-to-link-address mappings and next-hop delivery. DNS poisoning affects name-resolution data and address selection. Different caches, scopes and trust checks are involved.',['ARP local mapping','DNS name data','Different scopes/checks'])
],[src.arp,src.dns,src.tls]),
L('availability','DDoS & constrained resources','Explain availability failures by finding the resource that runs out.',['DDoS','amplification','rate limiting','bottleneck'],[
S('Availability depends on resources','Denial of service disrupts useful access by exhausting or breaking something the service needs. Distributed attacks use multiple sources or infrastructure. The bottleneck may be link bandwidth, connection state, CPU, worker capacity or a downstream database.'),
S('Traffic volume is not the whole story','A saturated access link can prevent delivery while server CPU is idle. A small number of expensive application requests can overwhelm backend work at low bandwidth. Measure the relevant resource and per-request cost rather than inferring the cause from request count alone.'),
S('Reflection and amplification','Some UDP services reply to an address supplied as the request source. Forged sources and larger responses can create reflected amplified traffic toward a victim. The key reasoning is the unverified source claim combined with an asymmetric response cost.'),
S('Act before the bottleneck','Upstream filtering and distributed capacity can help protect a saturated link. Rate limits, caching and work budgets address other resources. Host filtering happens after traffic crosses the access link. A defense must act where it can protect the particular resource without needlessly excluding legitimate users.')
],'Saturated access link → CPU may remain idle\nExpensive API → low volume, exhausted workers\nDefense location must protect the constrained resource.',
['Define user-visible failure.','Measure the constrained resource.','Reduce traffic or work before that bottleneck.','Verify useful service remains available.'],
'Extra server CPU does not add access-link bandwidth. Defense placement matters as much as the rule.',[
Q('Diagnose',['CPU is idle but the access link is saturated. Why might more workers not help?','Which resource needs protection in that situation?'],'Bandwidth is the bottleneck. More application workers neither increase link capacity nor remove traffic occupying it. Protection must act upstream or distribute traffic before the constrained segment.',['Link bottleneck','Workers do not add bandwidth','Upstream/distributed action']),
Q('Explain',['Why can host drop rules fail to restore an upstream link?','Where must filtering act to avoid consuming access-link capacity?'],'Packets have already crossed the access link before host filtering. Dropping can save host processing but not reclaim that bandwidth. Filtering or absorption before the saturated segment is needed to protect it.',['Link already consumed','Host cost differs','Before-bottleneck placement']),
Q('Reason',['An API fails at low bandwidth. What other resources could be exhausted?','Why is request count alone a poor measure of availability impact?'],'CPU, memory, database work, workers, connection pools or downstream quotas may saturate. Request costs differ. Measure resource usage and work per request before selecting controls.',['Application work costs','Several possible pools','Measure rather than assume'])
],[src.udp,src.tcp]),
L('capstone','From URL to evidence','Put the journey together and diagnose the last stage that actually worked.',['dependency','evidence','hypothesis','return path'],[
S('State your assumptions','For a simple fresh HTTPS load over HTTP/2, assume usable configuration, no relevant cache and no reused connection. Real browsers may use IPv6, encrypted DNS, HTTP/3, proxies or cached content. Stating assumptions makes an explanation precise.'),
S('Walk the dependencies','Name resolution itself requires routes and local delivery to a resolver. After an address is selected, route toward the endpoint and resolve the local next hop as needed. IPv4 NAT may translate traffic. Establish TCP, validate TLS, exchange HTTP and fetch additional resources needed by the page.'),
S('Use positive evidence','A DNS answer is not proof of server reachability. TCP setup proves transport state with a responder. A certificate-name error narrows attention to identity checks. HTTP errors may come from an intermediary. Find the last confirmed stage, then investigate the next dependency.'),
S('Close the reasoning loop','For each hypothesis, propose a test distinguishing it from another explanation. Record expected observations and what they would mean. Include return paths, filtering and existing state. A useful investigation ends with a defensible bounded conclusion and one concrete next test.')
],'Configuration → DNS (itself needs route/link delivery)\nSelected address → route + neighbor → possible NAT\nTCP → validated TLS → HTTP → additional resources',
['Record starting assumptions.','Draw client, router, resolver, edge and origin.','Label the last confirmed stage.','Choose one discriminating test.'],
'A full page can involve many origins and connections. The single-request model is a foundation, not a universal trace.',[
Q('Synthesize',['Explain a fresh HTTPS-over-TCP load, including dependencies of DNS itself.','Walk from a name to HTTP while stating the assumptions behind your sequence.'],'With no relevant caches or reused connection, reach the configured resolver using routes and local delivery. Resolve the name, select an address, route and resolve its next hop, account for NAT if present, establish TCP, validate TLS and exchange HTTP. Other resources or transports change the full sequence.',['DNS needs routing/link','Address, next hop, possible NAT','TCP/TLS/HTTP under stated assumptions']),
Q('Diagnose',['DNS and TCP work but TLS reports hostname mismatch. What do you inspect?','Which evidence would distinguish likely causes of a certificate-name error?'],'Compare exact URL name, certificate names and chain, reached endpoint and any proxy or virtual-host selection. DNS could point to an unintended endpoint, or hosting/certificate configuration could be wrong. Preserve validation while distinguishing causes.',['Expected versus certified name','Endpoint/proxy context','Multiple hypotheses; keep validation']),
Q('Investigate',['Turn “the Internet is broken” into a short investigation.','How would you narrow a vague browser failure into a testable hypothesis?'],'Record the exact error and scope. Inspect interface and route configuration, resolver responses, then intended transport and TLS/HTTP stages. Interpret each test narrowly, accounting for caches and filtering. Choose the next test from the last confirmed dependency.',['Exact symptom/scope','Configuration and protocol stages','Bounded interpretation and next test'])
],[src.ip,src.http,src.capture])
];
lessons.forEach((l,index)=>{l.index=index;l.chapter=Math.floor(index/4);l.minutes=10;l.questions.forEach((q,i)=>{q.id=`${l.id}-${i+1}`;q.lessonId=l.id;});});
export const questions=lessons.flatMap(l=>l.questions);
export const glossary={
'protocol':'An agreement defining message formats, meaning and expected behavior.',
'packet':'A network-layer unit, such as an IP header and payload, carried over local links.',
'frame':'A link-layer envelope for delivery across a local link.',
'encapsulation':'Wrapping one protocol’s data inside another protocol’s envelope.',
'MAC address':'A link-layer address for local delivery, not cryptographic identity.',
'switch':'A device forwarding local frames using learned link-address locations.',
'broadcast':'Delivery throughout a relevant broadcast domain; ordinary routers stop Ethernet broadcasts.',
'access point':'A device connecting Wi-Fi clients to a network, commonly bridging wireless and wired links.',
'IPv4':'Internet Protocol version 4, using 32-bit addresses.',
'prefix':'Leading address bits defining a network or routing range; /24 means 24 specified bits.',
'subnet':'An address subdivision identified by a prefix and relevant network configuration.',
'default gateway':'The next-hop router used by an applicable default route when no more specific route wins.',
'ARP':'Address Resolution Protocol: learns an on-link IPv4 neighbor’s link address.',
'neighbor cache':'Stored local-neighbor information including IP-to-link-address mappings and state.',
'next hop':'The immediate neighbor selected for forwarding a packet toward its destination.',
'DHCP':'Dynamic Host Configuration Protocol: supplies leases and options such as routers and resolvers.',
'lease':'Time-limited permission to use a supplied address, subject to renewal rules.',
'resolver':'Software or a service that obtains DNS answers for a client.',
'route':'A destination-range forwarding entry specifying a next hop, interface or other action.',
'longest prefix match':'Selecting the matching forwarding prefix with the most specified leading bits.',
'TTL':'DNS: ordinary cache lifetime in seconds. IP: forwarding hop limit. Context determines meaning.',
'MTU':'Maximum Transmission Unit: largest IP packet supported by a link without relevant adaptation.',
'ICMP':'Internet Control Message Protocol: diagnostic and error feedback, including echo and Time Exceeded.',
'NAT':'Network Address Translation: rewrites addresses; port translation can let flows share a public IPv4 address.',
'port':'A transport endpoint number. A number alone does not verify the service or its safety.',
'flow':'Related traffic grouped by protocol and endpoint information such as addresses and ports.',
'private address':'An address in a range reserved for private networking rather than ordinary global routing.',
'IPv6':'Internet Protocol version 6, using 128-bit addresses and mechanisms such as Neighbor Discovery.',
'Neighbor Discovery':'ICMPv6 mechanisms for local neighbors and routers, including link-address resolution.',
'SLAAC':'Stateless Address Autoconfiguration: forming IPv6 addresses using advertised prefixes and host behavior.',
'link-local':'Address scope limited to one link; important for IPv6 neighbor and router communication.',
'TCP':'Transmission Control Protocol: an ordered byte stream with connection state, loss recovery and flow/congestion controls.',
'socket':'An operating-system communication endpoint exposed through an application API.',
'handshake':'An exchange establishing protocol state or parameters; authentication depends on the protocol.',
'sequence number':'A position in TCP sequence space used for ordering bytes and control events.',
'acknowledgement':'Receipt feedback under protocol rules; a cumulative TCP ACK names the next contiguous byte expected.',
'flow control':'Restricting transmission according to the receiver’s available capacity.',
'congestion control':'Adjusting sending according to conditions along the network path.',
'UDP':'User Datagram Protocol: port-addressed datagrams without built-in ordering or retransmission.',
'datagram':'A discrete message unit. UDP retains delivered datagram boundaries rather than exposing a byte stream.',
'retransmission':'Sending data again after suspected loss; higher protocols may add it above UDP.',
'QUIC':'A secure UDP-carried transport with connections, reliable streams and congestion control.',
'DNS':'Domain Name System: a distributed name database with records, delegation and caches.',
'recursive resolver':'A DNS service obtaining answers for clients using caches and other DNS servers.',
'authoritative server':'A DNS server publishing authoritative data for a zone.',
'NXDOMAIN':'A DNS response code saying the queried domain name does not exist.',
'DNSSEC':'DNS Security Extensions: supports validation of signed data, not query confidentiality.',
'DoH':'DNS over HTTPS: protected client-to-resolver transport using HTTPS.',
'DoT':'DNS over TLS: protected client-to-resolver transport using TLS.',
'TLS':'Transport Layer Security: communication protection and configured peer authentication.',
'certificate':'Signed public-key and identity information, subject to validation and trust rules.',
'certificate authority':'An issuer in a certificate system; trust chains lead toward accepted trust anchors.',
'hostname':'A name used to identify a service context; the intended name matters in HTTPS validation.',
'key exchange':'A method for deriving shared secret material; authentication is a related separate requirement.',
'session key':'Secret key material for a protected session. Modern TLS derives separate traffic secrets and keys.',
'SNI':'Server Name Indication: TLS handshake information selecting the intended service; visibility depends on encrypted client hello.',
'TLS termination':'The endpoint where a TLS connection is decrypted and processed.',
'HTTP':'Hypertext Transfer Protocol: request/response semantics carried through different wire versions.',
'method':'An HTTP operation such as GET or POST with defined request semantics.',
'status code':'An HTTP numeric response indicator interpreted in the request context.',
'cache validator':'Metadata such as an ETag used to conditionally check a stored representation.',
'multiplexing':'Interleaving multiple logical exchanges over shared infrastructure.',
'HTTP/2':'A framed, multiplexed HTTP mapping commonly used over TLS and TCP.',
'HTTP/3':'HTTP mapped onto QUIC, using UDP as the underlying carrier.',
'cookie':'Browser-stored state sent under HTTP cookie scope and security rules.',
'session':'Application state linking interactions, commonly recognized through a token.',
'origin':'For ordinary web URLs, scheme, host and port used in browser security boundaries.',
'SameSite':'Cookie attribute affecting cross-site sending. A site is distinct from an origin.',
'CDN':'Content Delivery Network: distributed serving infrastructure, often with caching and proxying.',
'reverse proxy':'An intermediary accepting requests and forwarding selected work to upstream services.',
'load balancer':'A service distributing work among eligible backends.',
'origin server':'The source service behind an intermediary such as a CDN.',
'firewall':'Traffic policy enforcement using rules and observed context.',
'stateful filtering':'Filtering informed by tracked flow or connection state.',
'VPN':'Virtual Private Network: tunneled connectivity, commonly authenticated and encrypted.',
'tunnel':'Carrying inner communication inside another protocol between chosen endpoints.',
'capture point':'The interface or location from which traffic evidence is collected.',
'display filter':'A tool expression limiting displayed recorded packets without changing the recorded capture.',
'timeline':'An ordered account of observations with timestamps and bounded conclusions.',
'spoofing':'Presenting a false source or identity claim.',
'ARP poisoning':'Introducing misleading local IPv4-to-link-address mappings.',
'DNS poisoning':'Introducing unwanted name-related data into resolution or caches.',
'authentication':'Verifying identity or origin under a defined method and trust model.',
'DDoS':'Distributed Denial of Service: disruption using multiple sources or infrastructure.',
'amplification':'A small input producing a larger response or disproportionate resource cost.',
'rate limiting':'Restricting traffic or work over time under a defined grouping policy.',
'bottleneck':'The resource limiting useful throughput or availability under current conditions.',
'dependency':'A prerequisite another operation relies on, such as a route for a DNS query.',
'evidence':'An observation supporting a bounded conclusion, distinct from a proposed explanation.',
'hypothesis':'A proposed explanation that can be tested against alternatives.',
'return path':'The route and policy for responder-to-sender traffic; it can differ from the forward path.'
};
